\label{prop:balance}
For sufficiently regular solutions on an event-free interval,
\begin{equation}\label{eq:balance}
 \mathcal E_i'=-\mathcal L_i+\mathcal W_i,
\end{equation}
where
\begin{align}
 \mathcal L_1&=\int_\Omega\frac{\gamma}{\epsilon_0 s}|\mathbf{J}|^2dx,
 &\mathcal W_1&=\frac1{2\epsilon_0}\int_\Omega\left[\partial_t(s^{-1})|\mathbf{J}|^2+\partial_t(b/s)|\mathbf{P}|^2\right]dx,\label{eq:w1}\\
 \mathcal L_2&=\int_\Omega\frac{\gamma s}{\epsilon_0}|\mathbf{V}|^2dx,
 &\mathcal W_2&=\frac1{2\epsilon_0}\int_\Omega\left[(\partial_t s)|\mathbf{V}|^2+\partial_t(sb)|\mathbf{Q}|^2\right]dx
 -\int_\Omega (\partial_t s)\mathbf{E}\cdot \mathbf{Q}\,dx,\label{eq:w2}\\
 \mathcal L_3&=\int_\Omega\frac{\gamma s}{\epsilon_0}|\mathbf{V}|^2dx,
 &\mathcal W_3&=\frac1{2\epsilon_0}\int_\Omega\left[(\partial_t s)|\mathbf{V}|^2+\partial_t(sb)|\mathbf{Q}|^2\right]dx,\label{eq:w3}\\
 \mathcal L_4&=\int_\Omega\frac{\gamma s}{\epsilon_0}|\mathbf{V}|^2dx,
 &\mathcal W_4&=\frac1{2\epsilon_0}\int_\Omega\left[(\partial_t s)|\mathbf{V}|^2+\partial_t(b/s)|\mathbf{P}|^2\right]dx.\label{eq:w4}
\end{align}

\label{thm:semi}
Under Assumption~\ref{ass:coeff}, the HDG solution satisfies, on every event-free interval,
\begin{equation}\label{eq:semibalance}
 \partial_t \mathcal E_{i,h}+\mathcal D_h+\mathcal L_{i,h}=\mathcal W_{i,h},
\end{equation}
where the energies, loss, and modulation terms are exactly \eqref{eq:energy1}--\eqref{eq:energy4} and \eqref{eq:w1}--\eqref{eq:w4}, evaluated at discrete fields. The event identities \eqref{eq:ej1}--\eqref{eq:ej2} hold without additional projection loss. Consequently,
\begin{equation}\label{eq:semistab}
 \sup_{0\le t\le T}\mathcal E_{i,h}(t)\le G_i(T)\mathcal E_{i,h}(0).
\end{equation}

\label{lem:compat}
For either variant, the projected material equations are exact. The projected electromagnetic error satisfies
\begin{align}
 \left(\partial_t\mathbf{e}_D^h,\mathbf{v}\right)_{\mathcal T_h}-\left(\mathbf{e}_H^h,\nabla\times \mathbf{v}\right)_{\mathcal T_h}-\left\langle\mathbf{n}\times\widehat{\mathbf{e}}_H^h,\mathbf{v}\right\rangle_{\partial\mathcal T_h}
   &=-\sum_K\langle R_K,\mathbf{v}_T\rangle_{\partial K},\label{eq:erra}\\
 \left(\mu_0 \partial_t\mathbf{e}_H^h,\mathbf{w}\right)_{\mathcal T_h}+\left(\mathbf{e}_E^h,\nabla\times \mathbf{w}\right)_{\mathcal T_h}+\left\langle\mathbf{n}\times\widehat{\mathbf{e}}_{E_T}^h,\mathbf{w}\right\rangle_{\partial\mathcal T_h}&=0,\label{eq:errf}\\
 \left\langle\mathbf{n}\times\widehat{\mathbf{e}}_H^h,\widehat{\mathbf{v}}\right\rangle_{\partial\mathcal T_h}
   &=\sum_K\langle R_K,\widehat{\mathbf{v}}\rangle_{\partial K},\label{eq:errc}\\
 \mathbf{n}\times\widehat{\mathbf{e}}_H^h&=\mathbf{n}\times \mathbf{e}_H^h-\tau_K(\mathbf{e}_{E,T}^h-\widehat{\mathbf{e}}_{E_T}^h).\label{eq:errflux}
\end{align}
Here $\mathbf{v}\in W_h^E$, $\mathbf{w}\in W_h^H$, and $\widehat{\mathbf{v}}\in M_h^0$.

\label{lem:errorenergy}
Inside each event-free interval,
\begin{equation}\label{eq:errorbalance}
 \mathcal E_i(\mathbf{e}_i^h)' +\mathcal D_h(\mathbf{e}_i^h)+\mathcal L_i(\mathbf{e}_i^h)
 =\mathcal W_i(\mathbf{e}_i^h)-\sum_K\langle R_K,\mathbf{e}_{E,T}^h-\widehat{\mathbf{e}}_{E_T}^h\rangle_{\partial K},
\end{equation}
where $\mathcal D_h(\mathbf{e}_i^h)=\sum_K\tau_K\left\|\mathbf{e}_{E,T}^h-\widehat{\mathbf{e}}_{E_T}^h\right\|_{\partial K}^2$. Consequently,
\begin{equation}\label{eq:errineq}
 \mathcal E_i(\mathbf{e}_i^h)'+\tfrac12\mathcal D_h(\mathbf{e}_i^h)+\mathcal L_i(\mathbf{e}_i^h)
 \le C_i(t)\mathcal E_i(\mathbf{e}_i^h)+\tfrac12 F_h^2(t).
\end{equation}

\label{prop:resrates}
Variant A ($m=k$, $\tau_K\simeq1$) satisfies
\begin{equation}\label{eq:resA}
 F_h^2\le C\sum_K h_K^{2k+1}
 \left(|\mathbf{H}|_{H^{k+1}(K)}^2+|\mathbf{E}|_{H^{k+1}(K)}^2\right).
\end{equation}
Variant B ($m=k+1$, $\tau_K\simeq h_K^{-1}$) satisfies
\begin{equation}\label{eq:resB}
 F_h^2\le C\sum_K h_K^{2k+2}
 \left(|\mathbf{H}|_{H^{k+1}(K)}^2+|\mathbf{E}|_{H^{k+2}(K)}^2\right).
\end{equation}

\label{lem:integrated}
For projected initial continuous states,
\begin{equation}\label{eq:integrated}
 \sup_{0\le t\le T}\mathcal E_i(\mathbf{e}_i^h(t))+\int_0^T\mathcal D_h(\mathbf{e}_i^h(t))dt
 \le C G_i(T)\int_0^T F_h^2(t)dt.
\end{equation}
An initial projected error adds $C G_i(T)\mathcal E_i(\mathbf{e}_i^h(0))$.

\label{thm:error}
Assume Assumptions~\ref{ass:coeff} and \ref{ass:solution}, and exact state transfer. Initialize every continuous state by its block $L^2$ projection. For $i=1,2,4$,
\begin{equation}\label{eq:spatialerror}
 \sup_{0\le t\le T}\left\|Z_i(t)-Z_{i,h}(t)\right\|_{L^2(\Omega)}
 \le C h^{k+1}\left(\mathcal A_i+G_i(T)^{1/2}\mathcal B\right),
\end{equation}
and
\begin{equation}\label{eq:diss-error}
 \left(\int_0^T\sum_K\tau_K
 \left\|\mathbf{e}_{E,T}^h-\widehat{\mathbf{e}}_{E_T}^h\right\|_{\partial K}^2dt\right)^{1/2}
 \le C G_i(T)^{1/2}h^{k+1}\mathcal B.
\end{equation}
For model 3, \eqref{eq:spatialerror} first holds for $(\mathbf{E},\mathbf{H},\mathbf{Q},\mathbf{V})$. Adding $\mathbf{P},\mathbf{D}$ preserves the rate, with a constant also depending on $T,s^*$.

\label{prop:be}
For models 1, 2, and 4, let $t_n^*$ be $t_n^-$ for backward Euler and $t_{n-1/2}$ for midpoint. To distinguish the step energy metric from the model matrices $M_i$, set $\mathsf G_n^*=M_h(t_n^*)$ and $\mathcal E_n^*(Z)=\tfrac12\left\|Z\right\|_{\mathsf G_n^*}^2$. With $Z_n=Y_h^n$ for backward Euler and $Z_n=\overline Y_h^n$ for midpoint, both methods satisfy
\begin{equation}\label{eq:commonenergy}
 \mathcal E_n^*(Y_h^n)-\mathcal E_n^*(Y_h^{n-1})
 +\sigma\left\|Y_h^n-Y_h^{n-1}\right\|_{\mathsf G_n^*}^2
 +\Delta t_n\bigl(\mathcal D_h(Z_n;t_n^*)+\mathcal L_h(Z_n;t_n^*)\bigr)=0,
\end{equation}
where $\sigma=1/2$ for backward Euler and $\sigma=0$ for midpoint. In particular, for either method the step is uniquely solvable and contractive in its frozen energy for every $\Delta t_n>0$. Across steps and events,
\begin{equation}\label{eq:discretestability}
 \max_n\mathcal E_n^*(Y_h^n)\le G_i(T)\mathcal E_1^*(Y_h^0)
\end{equation}
with one-sided interpretation at event nodes; no CFL condition is required. For model 3 the same assertions hold in the reduced energy, and its independent polarization is controlled by summing its update.

\label{thm:full}
Use variant B and projected initial continuous states. Assume the spatial hypotheses of Theorem~\ref{thm:error}, and, for $i=1,2,4$, piecewise $W^{2,\infty}(I_j;L^2)$ regularity of the exact continuous state $Y_i$. Set
\[
 \mathcal T_i=\max_j\left\|\partial_t^2Y_i\right\|_{L^\infty(I_j;L^2)},\qquad
 \mathcal S=\sup_{t\in\cup_j\overline I_j}
 \left(|\mathbf{H}(t)|_{H^{k+1}(\mathcal T_h)}+|\mathbf{E}(t)|_{H^{k+2}(\mathcal T_h)}\right).
\]
For every event-aligned partition with positive steps, without a restriction on $\Delta t_{\max}$,
\begin{equation}\label{eq:fullrate}
 \max_n\left\|Z_i(t_n)-Z_{i,h}^n\right\|_{L^2(\Omega)}
 \le C\left[h^{k+1}(\mathcal A_i+\mathcal S)
                 +\Delta t_{\max}\mathcal T_i\right].
\end{equation}
Here $C$ can depend on $T$, coefficient and shape-regularity bounds, and $G_i(T)$, but is independent of $h$, the number of steps, and $\Delta t_{\max}$.

\label{thm:midfull}
Use variant B, exact event transfer, and the spatial assumptions of Theorem~\ref{thm:error}. For models 1, 2, and 4, the midpoint solution satisfies
\begin{equation}\label{eq:midfullrate}
 \max_n\left\|Z_i(t_n)-Z_{i,h}^n\right\|_{L^2(\Omega)}
 \le C h^{k+1}\bigl(\mathcal A_i+G_i(T)^{1/2}\mathcal B\bigr)
 +C G_i(T)^{1/2}T\,\Delta t^2\mathcal T_{i,h}^{\rm mid},
 \qquad \Delta t=\max_n \Delta t_n.
\end{equation}
The same rate holds for model 3's reduced state; it extends to $\mathbf P,\mathbf D$ with an additional $C T\Delta t^2\mathcal T_{P,h}^{\rm mid}$ term and the corresponding spatial projection bound. Constants outside the displayed regularity quantities are independent of the time partition. A mesh-uniform second-order bound follows if these semidiscrete regularity quantities are bounded independently of $h$; that bound is not established here.

\label{prop:timing}
Let $Y$ and $\widetilde Y$ solve the physical and shifted systems with identical initial continuous states. Suppose the shifted propagators satisfy
\[
 \left\|\widetilde U(t,r)\right\|\le C_U,\qquad 0\le r\le t\le T.
\]
For a continuous PDE, let $A_{j-1}$ and $A_j$ be the frozen Maxwell--material operators on the full-state $L^2$ space. Require, for almost every $r\in W_j$, that $Y(r)\in\mathcal D(A_{j-1})\cap\mathcal D(A_j)$, and that $(A_{j-1}-A_j)Y$ is strongly measurable and belongs to $L^1(W_j;L^2(\Omega))$. These common-domain and integrability assumptions are automatic for the finite-dimensional modal systems. Define
\begin{equation}\label{eq:Btiming}
 B_j=\mathop{\rm ess\,sup}_{r\in W_j}
        \left\|(A_{j-1}-A_j)Y(r)\right\|,
\end{equation}
and suppose $B_j<\infty$. An empty interval contributes zero. Then
\begin{equation}\label{eq:timingbound}
 \sup_{0\le t\le T}\left\|\widetilde Y(t)-Y(t)\right\|
 \le C_U\sum_{j=1}^{N_{\rm ev}} |\delta_j| B_j.
\end{equation}
For HDG the bound is uniform in $h$ only if $C_U$ and $B_j$ are uniform in $h$.

\label{prop:midtiming}
Fix the matrices, or let them range in a bounded smooth parameter family with fixed positive dwell times. Let $S_{\Delta t}^{\rm fit}$ be the midpoint product on a grid split at the physical switch, and $S_{\Delta t}^{\rm rnd}$ the midpoint product on a grid fitted to $\theta+\delta$, both with maximum step at most $\Delta t$ and final time $T$. Then
\begin{align}
 K(\theta)&=e^{(T-\theta)A_+}(A_--A_+)e^{\theta A_-},\label{eq:Ktiming}\\
 S_{\Delta t}^{\rm rnd}-S(\theta)&=\delta K(\theta)+O(\Delta t^2+\delta^2),\qquad
 S_{\Delta t}^{\rm fit}-S(\theta)=O(\Delta t^2).\label{eq:fitmidtiming}
\end{align}
Thus, when $|\delta|$ is comparable to $\Delta t$ and $K(\theta)Y_0\ne0$, the first-order timing term dominates midpoint's second-order integration error.

\label{prop:m2pulse}
Consider a homogeneous finite-dimensional model-2 evolution with a single change $s_-\ne s_+$ at $\theta$, and its exact shifted-switch evolution at $\theta+\delta$. Let their initial continuous states agree and suppose $\mathbf{Q}(\theta)\ne0$. Normalize the spatial mode to unit $L^2$ norm and set
\[
a=\frac{|s_+-s_-|}{\epsilon_0}\left\|\mathbf{Q}(\theta)\right\|>0.
\]
As $\delta\to0$, the continuous states have uniform error $O(|\delta|)$, but their algebraically reconstructed electric fields satisfy
\begin{align}
 \left\|\widetilde{\mathbf{E}}-\mathbf{E}\right\|_{L^\infty(0,T;L^2)}&=a+O(|\delta|),\label{eq:m2sup}\\
 \left\|\widetilde{\mathbf{E}}-\mathbf{E}\right\|_{L^2(0,T;L^2)}^2&=a^2|\delta|+O(\delta^2).\label{eq:m2L2}
\end{align}
In particular the latter field norm is bounded above and below by positive constant multiples of $|\delta|^{1/2}$, whereas the final-time field error is $O(|\delta|)$ if $T$ lies after both switches. The polarization $\mathbf{P}=s\mathbf{Q}$ has the same phenomenon, with jump amplitude $|s_+-s_-|\left\|\mathbf{Q}(\theta)\right\|$.
